import { inject, injectable } from "tsyringe";
import { Project, type ProjectProperties } from "../../domain/entities/Project";
import { Result } from "@/infrastructure/utils/result";
import { ProjectError } from "../../domain/errors/ProjectErrors";
import { IProjectRepository, IProjectRepositoryToken } from "../../domain/repositories/IProjectRepository";

export interface SyncProjectsInput {
    serverProjects: ProjectProperties[];
    localProjects: ProjectProperties[];
}

@injectable()
export class SyncProjectsUseCase {
    constructor(
        @inject(IProjectRepositoryToken)
        private projectRepository: IProjectRepository
    ) {}

    /**
     * Synchronizes projects between server and local storage.
     * In this implementation, server projects are considered the source of truth,
     * but we provide a hook for future conflict resolution logic.
     */
    async execute(input: SyncProjectsInput): Promise<Result<Project[], ProjectError>> {
        try {
            const { serverProjects } = input;

            // For now, we simply convert server properties to Project entities.
            // This can be expanded to handle complex merge logic if needed.
            const syncedProjects = serverProjects.map(props => new Project(props));

            return Result.ok(syncedProjects);
        } catch (error: any) {
            return Result.fail(ProjectError.internal(`Sync failed: ${error.message}`));
        }
    }
}

import { injectable } from "tsyringe";
import { ProjectApiClient } from "./ProjectApiClient";
import { LocalProjectService } from "../../infrastructure/storage/LocalProjectService";
import { Project, type ProjectProperties } from "../../domain/entities/Project";
import { Result } from "@/infrastructure/utils/result";
import { container } from "@/infrastructure/di/container";

@injectable()
export class ProjectSyncService {
    async syncProjects(): Promise<Result<Project[], Error>> {
        try {
            const apiClient = container.resolve(ProjectApiClient);
            const localService = container.resolve(LocalProjectService);

            const result = await apiClient.fetchProjects();

            if (result.isSuccess) {
                const serverProjects = result.getValue();
                const projects = serverProjects.map(props => new Project(props));

                // Update local storage in the background
                for (const project of projects) {
                    await localService.saveProject(project.toProperties());
                }

                return Result.ok(projects);
            }

            // Fallback to local storage if API fails
            console.warn('Project sync failed, falling back to local storage:', result.error);
            const localProjectsProps = await localService.getAllProjects();
            const localProjects = localProjectsProps.map(props => new Project(props));

            return Result.ok(localProjects);
        } catch (error: any) {
            return Result.fail(error instanceof Error ? error : new Error(String(error)));
        }
    }
}

