        return this.verifyPaymentUseCase.execute(params);
    }

    async submitPaymentRequest(params: { 
        file: Buffer, 
        fileName: string, 
        contentType: string, 
        userId: string, 
        planId: string, 
        planName: string, 
        credits: number, 
